create database banking_fraud_detection;
use banking_fraud_detection;
create table customers
(customer_id int primary key ,
 custemer_name varchar(100), 
 email varchar(100), 
 phone varchar(15), 
 city varchar(50)
 );

select * from customers;

CREATE TABLE accounts (
    account_id INT PRIMARY KEY,
    customer_id INT,
    account_type VARCHAR(20),
    balance DECIMAL(15,2),
    account_status VARCHAR(20),

    FOREIGN KEY (customer_id)
        REFERENCES customers(customer_id)
);

CREATE TABLE transactions (
    transaction_id INT PRIMARY KEY,
    account_id INT,
    amount DECIMAL(15,2),
    transaction_type VARCHAR(20),
    transaction_date DATETIME,
    location VARCHAR(100),
    transaction_status VARCHAR(20),

    FOREIGN KEY (account_id)
        REFERENCES accounts(account_id)
);


CREATE TABLE fraud_alerts (
    alert_id INT PRIMARY KEY,
    transaction_id INT,
    fraud_type VARCHAR(100),
    risk_level VARCHAR(20),
    alert_status VARCHAR(20),
    alert_date DATETIME,

    FOREIGN KEY (transaction_id)
        REFERENCES transactions(transaction_id)
);



CREATE TABLE beneficiaries (
    beneficiary_id INT PRIMARY KEY,
    customer_id INT,
    beneficiary_name VARCHAR(100),
    bank_name VARCHAR(100),
    account_number VARCHAR(30),

    FOREIGN KEY (customer_id)
        REFERENCES customers(customer_id)
);



CREATE TABLE login_logs (
    login_id INT PRIMARY KEY,
    customer_id INT,
    login_time DATETIME,
    ip_address VARCHAR(45),
    location VARCHAR(100),
    login_status VARCHAR(20),

    FOREIGN KEY (customer_id)
        REFERENCES customers(customer_id)
);



CREATE TABLE cards (
    card_id INT PRIMARY KEY,
    account_id INT,
    card_type VARCHAR(20),
    card_number VARCHAR(20),
    expiry_date DATE,
    card_status VARCHAR(20),

    FOREIGN KEY (account_id)
        REFERENCES accounts(account_id)
);

-- Synthetic test data only. Card numbers are not payment credentials.


CREATE TABLE loans (
    loan_id INT PRIMARY KEY,
    customer_id INT,
    loan_type VARCHAR(50),
    loan_amount DECIMAL(15,2),
    interest_rate DECIMAL(5,2),
    loan_status VARCHAR(20),

    FOREIGN KEY (customer_id)
        REFERENCES customers(customer_id)
);

-- Loan records


CREATE TABLE branches (
    branch_id INT PRIMARY KEY,
    branch_name VARCHAR(100),
    city VARCHAR(50),
    manager_name VARCHAR(100)
);



CREATE TABLE employees (
    employee_id INT PRIMARY KEY,
    branch_id INT,
    employee_name VARCHAR(100),
    designation VARCHAR(50),
    salary DECIMAL(12,2),

    FOREIGN KEY (branch_id)
        REFERENCES branches(branch_id)
);



-- 🏦 Banking Fraud Detection — 40 SQL Questions

-- 🔥 Advanced Customer & Account Analysis

-- 1. Find the top 10 customers based on their total transaction amount.? 
select a.customer_id, a.custemer_name, SUM(c.amount) as total_transaction_amount
from customers a
join accounts b on a.customer_id = b.customer_id
join transactions c on b.account_id = c.account_id
group by a.customer_id, a.custemer_name
order by total_transaction_amount desc limit 10;


-- 2. Find customers who have more than one bank account.?
select a.customer_id, a.custemer_name, count(b.account_id) as total_accounts
from customer a
join accounts b on a.customer_id=b.customer_id
group by a.customer_id, a.custemer_name
having count(b.account_id) > 1;

SELECT 
    c.customer_id,
    c.custemer_name,
    COUNT(a.account_id) AS total_accounts
FROM customers c
JOIN accounts a
    ON c.customer_id = a.customer_id
GROUP BY c.customer_id, c.custemer_name
HAVING COUNT(a.account_id) >= 1;